'use strict';
// The ORDER control. Overriding an inherited untyped method is admitted
// only for a class the whole-program collect pass can see -- a class
// DECLARATION at module top level. A class EXPRESSION, or a class declared
// inside a function body, registers with its base only when its containing
// statement lowers, and a call to the method compiled before that point has
// already resolved to the base's body. `genericOverrideBelow` reads that
// subclass list, so outside the collect window its answer is not an answer.
//
// It refuses by name instead. Before the guard this file built clean and
// printed the BASE's answer for the subclass instance, at exit 0.
//
// The hierarchy is its own -- reusing index.js's `Base` would fence at the
// CALL instead, because `Pooled` already makes `genericOverrideBelow` true
// there, and then this file would prove nothing about ordering.
class LateBase {
  constructor(n) {
    this.n = n;
  }

  end(callback) {
    return 'LateBase.end<' + this.n + '>' + (callback === null ? '' : '!');
  }
}

/** @param {LateBase} c */
function callIt(c) {
  return c.end(null);
}

// Instantiates callIt -- and resolves its `c.end` -- before the subclass
// below exists.
const first = callIt(new LateBase('B'));

const Late = class extends LateBase {
  end(callback) {
    return 'Late.end<' + this.n + '>' + (callback === null ? '' : '!');
  }
};

exports.first = first;
exports.second = callIt(new Late('L'));
